FHLang.tambah({ terapkan: false, kamus: { "Klasifikasi citra Sentinel-2 (pembanding mandiri)": "Sentinel-2 image classification (independent comparison)", "Model belajar dari peta KLHK 2025 & PRCF · akurasi diuji pada wilayah terpisah": "Model trained on the 2025 KLHK & PRCF maps · accuracy tested on separate areas",
  "Hasil klasifikasi citra belum tersedia.": "Image classification results are not yet available.", "Akurasi keseluruhan (uji wilayah terpisah)": "Overall accuracy (separate-area test)", "Kappa": "Kappa", "Akurasi hutan vs bukan hutan": "Forest vs non-forest accuracy", "Sampel latih / uji": "Training / test samples",
  "Akurasi pembuat": "Producer's accuracy", "Akurasi pengguna": "User's accuracy", "Terpetakan (tanpa awan)": "Mapped (cloud-free)" },
  rx: [[/^Akurasi per sumber label: (.+)\.$/, m => `Accuracy per label source: ${m[1].replace(/piksel uji/g, 'test pixels')}.`],
       [/^Model Random Forest dilatih dari (.+) piksel sampel .*$/, m => `A Random Forest model trained on ${m[1]} sample pixels (6 Sentinel-2 band reflectances, vegetation/water/moisture indices, 5×5 texture, elevation & slope) taken from the interior of the 2025 KLHK Land Cover Map polygons and the 2025 PRCF map (Nanga Lauk). Accuracy is computed on 2 km blocks not used for training. These figures are an independent image-based comparison – not a replacement for the official map; spectrally similar classes (e.g. shrub vs agriculture mixed with shrub) are confused most often.`]] });
FHLang.tambah({ terapkan: false, kamus: { "Akurasi 4 kelompok (uji wilayah terpisah)": "4-group accuracy (separate-area test)", "Akurasi kelas rinci (tidak ditampilkan)": "Detailed-class accuracy (not shown)", "Kelompok tutupan lahan": "Land cover group",
  "Lahan basah bukan hutan": "Non-forest wetland", "Lahan kering bukan hutan": "Non-forest dryland", "Tubuh air": "Water body" },
  rx: [[/^Akurasi kelas rinci per sumber label: (.+)\.$/, m => `Detailed-class accuracy per label source: ${m[1].replace(/piksel uji/g, 'test pixels')}.`],
       [/^Model Random Forest dilatih dari (.+) piksel sampel .*Hasil ditampilkan per 4 kelompok.*$/, m => `A Random Forest model trained on ${m[1]} sample pixels (6 Sentinel-2 band reflectances, vegetation/water/moisture indices, 5×5 texture, elevation & slope) taken from the interior of the 2025 KLHK Land Cover Map polygons and the 2025 PRCF map (Nanga Lauk). Accuracy is computed on 2 km blocks not used for training. Results are shown in 4 groups because detailed-class accuracy is still low (the 1:250,000 KLHK labels are coarse; shrub, agriculture mixed with shrub, settlements & bare land are often confused). These figures are an independent image-based comparison – not a replacement for the official map.`]] });
